-- Explicações por artigo — Lei de Enfrentamento ao Tráfico de Pessoas (Lei nº 13.344, de 2016). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei dispõe sobre o tráfico de pessoas cometido no território nacional contra vítima brasileira ou estrangeira e no exterior contra vítima brasileira. O enfrentamento ao tráfico de pessoas compreende a prevenção e a repressão desse delito, bem como a atenção às suas vítimas.', '["Alcance: tráfico no território nacional (vítima brasileira ou estrangeira) e no exterior (vítima brasileira).","Três eixos: prevenção, repressão e atenção às vítimas."]'::jsonb, '["Estrutura em três eixos: PREVENÇÃO, REPRESSÃO e ATENÇÃO ÀS VÍTIMAS."]'::jsonb, 'A política abrange tanto o aliciamento de brasileiros para o exterior quanto o de estrangeiros no Brasil.', '["Assertiva que limita a Lei às vítimas estrangeiras erra: abrange brasileiras e estrangeiras."]'::jsonb, '[]'::jsonb, '["Art. 149-A do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O enfrentamento ao tráfico de pessoas atenderá aos princípios do respeito à dignidade da pessoa humana; da promoção e garantia da cidadania e dos direitos humanos; da universalidade, indivisibilidade e interdependência; da não discriminação por motivo de gênero, orientação sexual, origem étnica ou social, procedência, nacionalidade, atuação profissional, raça, religião, faixa etária, situação migratória ou outro status; da transversalidade dessas dimensões nas políticas públicas; da atenção integral às vítimas diretas e indiretas, independentemente de nacionalidade e de colaboração em investigações; e da proteção integral da criança e do adolescente.', '["Dignidade da pessoa humana e direitos humanos.","Universalidade, indivisibilidade e interdependência.","Não discriminação e transversalidade.","Atenção integral às vítimas, independentemente de colaboração.","Proteção integral da criança e do adolescente."]'::jsonb, '["A assistência à vítima NÃO depende de colaboração com a investigação."]'::jsonb, 'A vítima estrangeira recebe atendimento mesmo sem aceitar depor.', '["Assertiva que condiciona a atenção à vítima à sua colaboração com o processo erra."]'::jsonb, '[{"termo":"Transversalidade","significado":"Incorporar uma preocupação em todas as políticas públicas."}]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O enfrentamento ao tráfico de pessoas atenderá às diretrizes de fortalecimento do pacto federativo; articulação com organizações governamentais e não governamentais, nacionais e estrangeiras; incentivo à participação da sociedade em instâncias de controle social; estruturação da rede de enfrentamento; fortalecimento da atuação em áreas de maior incidência, como fronteiras, portos, aeroportos, rodovias e estações; estímulo à cooperação internacional; incentivo a estudos e pesquisas; preservação do sigilo dos procedimentos; e gestão integrada para coordenação da política e dos planos nacionais.', '["Atuação conjunta das esferas de governo.","Articulação com organizações nacionais e estrangeiras.","Foco em fronteiras, portos, aeroportos e rodovias.","Cooperação internacional.","Sigilo dos procedimentos."]'::jsonb, '["Lista de diretrizes (nove incisos)."]'::jsonb, 'A política reforça a atuação nas regiões de fronteira e nos aeroportos.', '["Assertiva que exclui a cooperação internacional das diretrizes erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prevenção ao tráfico de pessoas dar-se-á por meio da implementação de medidas intersetoriais e integradas nas áreas de saúde, educação, trabalho, segurança pública, justiça, turismo, assistência social, desenvolvimento rural, esportes, comunicação, cultura e direitos humanos; de campanhas socioeducativas e de conscientização; do incentivo à mobilização da sociedade civil; e do incentivo a projetos de prevenção.', '["Medidas intersetoriais em várias áreas.","Campanhas socioeducativas.","Participação da sociedade civil.","Projetos de prevenção."]'::jsonb, '["Prevenção é multissetorial, e não só policial."]'::jsonb, 'Campanhas em escolas orientam sobre falsas ofertas de emprego no exterior.', '["Assertiva que restringe a prevenção à área de segurança pública erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A repressão ao tráfico de pessoas dar-se-á por meio da cooperação entre órgãos do sistema de justiça e segurança, nacionais e estrangeiros; da integração de políticas e ações de repressão aos crimes correlatos e da responsabilização dos seus autores; e da formação de equipes conjuntas de investigação.', '["Cooperação entre órgãos nacionais e estrangeiros.","Integração da repressão a crimes correlatos.","Equipes conjuntas de investigação."]'::jsonb, '["Equipes conjuntas podem envolver órgãos estrangeiros."]'::jsonb, 'A Polícia Federal e uma polícia estrangeira formam equipe conjunta de investigação.', '["Assertiva que veda a cooperação com órgãos estrangeiros na repressão erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A proteção e o atendimento à vítima direta ou indireta do tráfico de pessoas compreendem assistência jurídica, social, de trabalho e emprego e de saúde; acolhimento e abrigo provisório; atenção às necessidades específicas; preservação da intimidade e da identidade; prevenção à revitimização; atendimento humanizado; e informação sobre os procedimentos. A atenção dá-se com a interrupção da situação de exploração, a reinserção social, o acesso à educação, cultura, formação e trabalho e, para crianças e adolescentes, a reinserção familiar e comunitária. No exterior, a assistência imediata a brasileiras cabe à rede consular, independentemente da situação migratória. A assistência à saúde compreende a recuperação física e psicológica.', '["Assistência jurídica, social, de trabalho e de saúde.","Acolhimento e abrigo provisório.","Preservação da intimidade e da identidade.","Prevenção à revitimização.","No exterior, assistência pela rede consular."]'::jsonb, '["Rede consular presta assistência independentemente da situação migratória."]'::jsonb, 'A vítima brasileira resgatada no exterior recebe assistência no consulado.', '["Assertiva que condiciona a assistência consular à regularidade migratória da vítima erra."]'::jsonb, '[{"termo":"Revitimização","significado":"Nova violência causada à vítima pelo próprio atendimento."}]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo acrescentou à antiga Lei do Estrangeiro (hoje substituída pela Lei de Migração) dispositivos que concediam residência permanente às vítimas de tráfico de pessoas no território nacional, independentemente de sua situação migratória e de colaboração em procedimento administrativo, policial ou judicial, com possibilidade de extensão por reunião familiar a cônjuges, companheiros, ascendentes, descendentes e outros dependentes, com isenção de multas e taxas, e previu que o estrangeiro estaria em situação regular enquanto tramitasse pedido de regularização migratória.', '["Residência permanente para vítima de tráfico no território nacional.","Independe de situação migratória e de colaboração.","Extensão à família por reunião familiar.","Isenção de multas e taxas.","Regularidade enquanto tramita o pedido."]'::jsonb, '["ATUALIZAÇÃO: o Estatuto do Estrangeiro foi revogado pela Lei de Migração; consulte o regime vigente.","Colaboração com a investigação NÃO é condição."]'::jsonb, 'A estrangeira vítima de tráfico no Brasil pode obter residência permanente sem depor.', '["Assertiva que condiciona a residência permanente à colaboração com o processo erra."]'::jsonb, '[]'::jsonb, '["Lei de Migração"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, de ofício, a requerimento do Ministério Público ou por representação do delegado de polícia, ouvido o Ministério Público, havendo indícios suficientes de infração penal, poderá decretar medidas assecuratórias relativas a bens, direitos ou valores do investigado ou acusado, ou em nome de interpostas pessoas, que sejam instrumento, produto ou proveito do tráfico de pessoas, na forma dos arts. 125 a 144-A do Código de Processo Penal. Procede-se à alienação antecipada quando houver deterioração ou dificuldade de manutenção. O juiz libera os bens de origem lícita, mantendo os necessários à reparação dos danos e ao pagamento de multas e custas. Nenhum pedido de liberação será conhecido sem o comparecimento pessoal do acusado ou da interposta pessoa. Na sentença, o juiz decide sobre o perdimento.', '["Medidas assecuratórias sobre bens do tráfico de pessoas.","Alienação antecipada em caso de deterioração.","Liberação de bens de origem lícita.","Comparecimento pessoal para pedido de liberação.","Perdimento decidido na sentença."]'::jsonb, '["Semelhante ao regime da Lei de Lavagem.","Comparecimento pessoal exigido para a liberação."]'::jsonb, 'O juiz bloqueia imóvel adquirido com o lucro do aliciamento.', '["Assertiva que permite a liberação dos bens sem comparecimento pessoal do acusado erra."]'::jsonb, '[]'::jsonb, '["Lei de Lavagem de Dinheiro"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplica-se subsidiariamente, no que couber, o disposto na Lei de Organizações Criminosas aos casos de tráfico de pessoas.', '["Aplicação subsidiária da Lei de Organizações Criminosas."]'::jsonb, '["Permite meios de prova como colaboração premiada e infiltração, no que couber."]'::jsonb, 'A investigação do tráfico de pessoas pode usar colaboração premiada.', '["Assertiva que afasta a Lei de Organizações Criminosas do tráfico de pessoas erra."]'::jsonb, '[]'::jsonb, '["Lei de Organizações Criminosas"]'::jsonb, 'under_review', 'claude'
